D[89009]={"^Cripples the target, reducing movement speed by (.-)%% for (.-)%.%s*$","Entorpece o alvo, reduzindo sua velocidade de movimento {{1}}% durante {{2}}."}
D[89010]={"^Poisons the enemy, reducing all healing effects used on them by (.-) for (.-)%.%s*$","Envenena o inimigo, reduzindo todos efeitos de cura utilizados sobre ele {{1}} durante {{2}}."}
D[89011]={"^Stuns an enemy for (.-)%. Must be stealthed%.%s*$","Atordoa contra o inimigo durante {{1}}. Tem questar em Furtividade."}
D[89012]={"^Places banner on corpse of Lord Xiz%.%s*$","Coloca o estandarte sobre o cadáver de Lorde Xiz."}
D[89013]={"^Absorbs (.-) Frost damage on all nearby party members%.  Lasts (.-)%.%s*$","Absorve {{1}} de dano de Gelo sobre todos membros do grupo próximos. Dura {{2}}."}
