D[89024]={"^Restores (.-) health per second to nearby party members for (.-)%.%s*$","Recupera {{1}} de vida por segundo aos membros aliados que se encontrem perto durante {{2}}."}
D[89025]={"^Increases the critical strike rating of nearby party members by (.-) for (.-)%.%s*$","Aumenta o índice de acerto crítico dos aliados que se encontrem perto em {{1}} durante {{2}}."}
D[89026]={"^All stats of nearby party members increased by (.-) for (.-)%.%s*$","Aumentadas todas as estatísticas dos membros do grupo {{1}} durante {{2}}."}
D[89027]={"^Increases spell power by (.-) for all nearby party members%.  Lasts (.-)%.%s*$","Aumenta o poder mágico de todos membros do grupo próximos até {{1}} Dura {{2}}."}
D[89028]={"^Spell power increased by (.-)%.%s*$","poder mágico aumentou {{1}} p."}
D[89029]={"^Summons the Felsteel Boar to fight for you for 30 seconds%.%s*$","Evocar ao javali de aço vil para que lute a seu lado durante 30 s."}
D[89030]={"^Bashes the target, knocking its lights out for (.-)%.%s*$","Azota o alvo, deixando-lhe sem lucidez durante {{1}}."}
D[89031]={"^The target forgets what he was going to say, becoming silenced for (.-)%.%s*$","O alvo olvidao que ia a dizer e se queda silenciado durante {{1}}."}
D[89032]={"^Causes the caster to become confused when attacked with powerful fire spells%.%s*$","Faz com que o conjurador entrem confusão quando lhe ataquem com feitiços de Fogo poderosos."}
D[89033]={"^You're on fire!%s*$","Está ardendo!"}
D[89034]={"^Read the marked page at the southern end of the Master's Terrace%.%s*$","Leia a página desmarcada no extremo sul do Bancal do Mestre."}
