D[89080]={"^Silences nearby enemies for (.-)%.%s*$","silencia os inimigos próximos durante {{1}}."}
D[89081]={"^Inflicts weapon damage plus (.-) to an enemy and its nearest allies, affecting up to (.-) targets and knocking them back%.%s*$","Causa dano com arma mais {{1}} um inimigo e seus aliados próximos. Afeta até {{2}} alvos e os derruba."}
