D[89100]={"^Melee and movement speed increased by (.-)%% for (.-)%.%s*$","Velocidades de movimento e de corpo a corpo aumentadas {{1}}% durante {{2}}."}
D[89101]={"^Regenerate (.-) health and mana per 5 sec for (.-)%.%s*$","Regeneram {{1}} de vida e de mana a cada 5 s durante {{2}}."}
D[89102]={"^Healing reduced by (.-)%% for (.-)%.%s*$","Cura reduzida em {{1}}% durante {{2}}."}
D[89103]={"^Inflicts (.-) Arcane damage to enemies in an area around the caster%.%s*$","Causa {{1}} de dano Arcano os inimigos que se encontram ao redor do conjurador."}
D[89104]={"^Deals (.-) damage to all enemies within (.-) yards, knocking them back%.%s*$","Causa {{1}} de dano a todos inimigos em um raio de {{2}} m, lançando-os para trás."}
D[89105]={"^Compresses the target's lungs, dealing (.-) damage every (.-) sec for (.-)%.%s*$","Comprime os pulmões do alvo, causando-lhe {{1}} de dano a cada {{2}} s durante {{3}}."}
D[89106]={"^Empty the vial's contents onto the eternal flame in the Alonsus Chapel%.%s*$","Vazio o conteúdo vial sobre a chama eterna na Capilha de Alonseus."}
D[89107]={"^Increases attack power and ranged attack power for all friendly units within (.-) by (.-)%.%s*$","Aumenta o poder de ataque o poder de ataque à distância de todas as unidades aliadas em um raio de {{1}} {{2}} p."}
D[89108]={"^Encases you in magic, causing spells to be reflected back upon their target (.-)%% of the time for (.-)%.%s*$","Te reviste de magia, provocando que os feitiços ricocheteiem contra o seu alvo {{1}}% do tempo durante {{2}}."}
D[89109]={"^Regenerates health over time%.  Lasts (.-)%.%s*$","Regeneram vida no tempo. Dura {{1}}."}
