D[90979]={"^Fills your Brewfest Stein at a Brewfest Festive Keg%.%s*$","Relhena seu jarra dá Festa dá cerveja em um barril festivo dá Festa dá cerveja."}
D[90980]={"^A sample of Barleybrew Clear%.%s*$","Uma mostra de cebadiz clara."}
D[90981]={"^Slows Supremus, reducing his movement speed by (.-)%%%.%s*$","Desacelera a Supremus, reduz sua velocidade de movimento {{1}}%."}
