D[90985]={"^Charges a distant enemy%.%s*$","Carga contra um inimigo distante."}
D[90986]={"^Reduces an enemy's movement speed by (.-)%% and deals (.-) physical damage every (.-) for (.-)%.%s*$","Reduz a velocidade de movimento {{1}}% e causa {{2}} de dano Físico cada {{3}} durante {{4}}."}
D[90987]={"^A sample of Thunder 45%.%s*$","Uma mostra de Trovão 45."}
